function entropy(probs){ var H=0; for(var i=0;i<probs.length;i++){ var p=probs[i]; if(p>0) H += -p*Math.log2(p); } return H; }
function entropyFromCounts(counts){ var tot=0; for(var i=0;i<counts.length;i++) tot+=counts[i];
  var H=0; for(var i=0;i<counts.length;i++){ var p=counts[i]/tot; if(p>0) H += -p*Math.log2(p); } return H; }
var EXPORTS={entropy:entropy,entropyFromCounts:entropyFromCounts};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ShannonForgePure = EXPORTS; }
